const svgIcon=n=>SVGI[n]?SVG_HEAD+SVGI[n][2]+"</svg>":"";
/* "@name" -> name; an old emoji / symbol -> the SVG that replaces it; anything else (L1, A, OK, ...) -> "" and stays plain text */
const svgName=ic=>{if(!ic)return"";ic=String(ic);if(ic[0]==="@")return SVGI[ic.slice(1)]?ic.slice(1):"";return LEG[ic.replace(/\uFE0F/g,"")]||""};
const iconHtml=ic=>{const n=svgName(ic);return n?svgIcon(n):""};
/* the small <i class="ico" data-i="name"> placeholders in the menu and editor become SVG here */
const hydrate=(r=root)=>r.querySelectorAll("[data-i]").forEach(e=>{if(!e.firstChild)e.innerHTML=svgIcon(e.dataset.i)});
hydrate();
